import os


def safe_join(base_dir, filename):
    if "\0" in filename:
        raise ValueError("invalid filename")
    base = os.path.realpath(base_dir)
    # realpath resolves "..", absolute paths and symlinks before the containment check
    path = os.path.realpath(os.path.join(base, filename))
    if path == base or os.path.commonpath([base, path]) != base:
        raise ValueError("path escapes base directory")
    return path

import os


def safe_join(base_dir, filename):
    """Return the path of `filename` inside `base_dir`; raise ValueError if it would escape."""
    if not filename or "\0" in filename:
        raise ValueError("invalid filename")
    base = os.path.realpath(base_dir)
    # realpath resolves "..", absolute paths and symlinks before the containment check
    path = os.path.realpath(os.path.join(base, filename))
    if os.path.commonpath([base, path]) != base or path == base:
        raise ValueError("path escapes base directory")
    return path


if __name__ == "__main__":
    import tempfile

    with tempfile.TemporaryDirectory() as d:
        base = os.path.realpath(d)
        assert safe_join(d, "a.txt") == os.path.join(base, "a.txt")
        assert safe_join(d, "sub/../a.txt") == os.path.join(base, "a.txt")
        os.symlink("/etc", os.path.join(d, "link"))
        for bad in ["../x", "/etc/passwd", "a/../../x", "", ".", "a\0b", "link/passwd"]:
            try:
                safe_join(d, bad)
            except ValueError:
                pass
            else:
                raise AssertionError(bad)
    print("ok")

